<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import AppPage from '../AppPage.vue'
import AppNavbar from '@/components/AppNavbar.vue'
import AppButton from '@/components/AppButton.vue'
import BaseCard from '@/components/BaseCard.vue'
import SectionHeader from '@/components/SectionHeader.vue'
import StatusTag from '@/components/StatusTag.vue'
import Stage1Field from './Stage1Field.vue'
import Stage1Status from './Stage1Status.vue'
import {useStage1Page} from '../../services/use-stage1-page'
import {stage1Service,label} from '../../services/stage1'
import type {Data,Page} from '../../services/stage1'
const props=defineProps<{editor?:boolean;query?:Data}>(),p=useStage1Page('staff_'+(props.query?.id||'new'))
const {error,busy,loading,pending,dirty}=p,people=ref<Page<Data>>({records:[],total:0}),invitations=ref<Page<Data>>({records:[],total:0}),roles=ref<Data[]>([]),detail=ref<Data|null>(null),issued=ref<Data|null>(null),page=ref(1),invitePage=ref(1),form=ref<Data>({roleIds:[],reason:''}),action=ref<Data|null>(null)
const roleLabels:Record<string,string>={GOODS_OPERATOR:'商品管理',INVENTORY:'库存管理',POINT:'点位管理',READ_ONLY:'只读经营',PROFILE_MAINTAINER:'资料维护',COST_VIEWER:'成本查看',COST_EDITOR:'成本维护',FULFILLMENT_EDITOR:'履约配置',COOPERATION_VIEWER:'合作信息查看',S3_FULFILLMENT:'订单履约操作',S3_ORDER_READER:'订单查询',S3_VERIFIER:'到店与自提核销',S45_AFTERSALE_READER:'售后查询',S45_AFTERSALE_REVIEWER:'售后审核',S45_EVALUATION_READER:'评价查询',S45_FUNDS_READER:'资金查询',S45_RETURN_RECEIVER:'退货收货'}
const options=computed(()=>roles.value.map(r=>({value:r.id,label:roleLabels[r.name]||r.name})))
const roleNames=(ids:string[])=>ids.map(id=>options.value.find(r=>r.value===id)?.label||id).join('、')
function load(){return p.read<Data>(async()=>({roles:await stage1Service.read<Data[]>('/staff-role-options'),...(props.editor?{detail:props.query?.id?await stage1Service.read<Data>('/staff/'+props.query.id):null}:{people:await stage1Service.read<Page<Data>>('/staff',{pageNumber:page.value,pageSize:20}),invitations:await stage1Service.read<Page<Data>>('/staff-invitations',{pageNumber:invitePage.value,pageSize:20})})}),v=>{roles.value=v.roles;if(props.editor){detail.value=v.detail||null;form.value={roleIds:v.detail?.person.roleIds||[],reason:''}}else{people.value=v.people!;invitations.value=v.invitations!}dirty.value=false})}
async function save(){await p.write(()=>p.command<Data>(detail.value?'/staff/'+detail.value.person.id+'/roles':'/staff-invitations',{...form.value,...(detail.value?{expectedVersion:detail.value.person.version}:{})},detail.value?'PUT':'POST'),v=>{if(detail.value)return load();else{issued.value=v;form.value={roleIds:[],reason:''}}})}
function edit(id?:string){uni.navigateTo({url:'/pages/staff/editor/index'+(id?'?id='+id:'')})}
function prepare(row:Data,kind:string,verb:string){action.value={row,kind,verb,reason:''}}
async function execute(){const selected=action.value!;const yes=await uni.showModal({title:'确认'+(({confirm:'授权此人',reject:'拒绝申请',revoke:'撤销',enable:'恢复权限',disable:'停用权限'} as Record<string,string>)[selected.verb]||'操作')+'？',content:selected.verb==='confirm'?'请核对已认证人员身份和用途。接受邀请不会自动获得权限，本次确认后才生效。':'此操作保留历史，并按最新授权立即检查访问。'});if(!yes.confirm)return;await p.write(()=>p.command('/'+selected.kind+'/'+selected.row.id+'/'+selected.verb,{expectedVersion:selected.row.version,reason:selected.reason}),()=>{action.value=null;return load()})}
function copy(){if(!issued.value?.invitationToken)return;uni.setClipboardData({data:issued.value.invitationToken,showToast:false,success:()=>uni.showToast({title:'已复制，请私下交给受邀人',icon:'none'})})}
function recover(){return p.recover<Data>(v=>{if(v.deliveryStatus||v.status==='INVITED'){issued.value=v;error.value='原操作已受理。邀请口令只显示一次；若未收到口令，请在邀请列表撤销后重新创建。'}else return load()})}
onMounted(load);onShow(()=>{if(!props.editor&&!pending.value&&!action.value)return load()})
function back(){uni.navigateBack()}
</script>
<template><AppPage secondary :status="loading&&!roles.length?'loading':'ready'"><template #navbar><AppNavbar :title="editor?(detail?'人员授权':'邀请工作人员'):'工作人员'" centered show-back/></template><view class="s1-staff stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="recover" @retry="p.retry(load)" @abandon="p.abandon(load)"/>
<template v-if="editor"><BaseCard class="s1-form"><SectionHeader :title="detail?detail.person.displayName:'选择工作权限'"/><text v-if="detail">可信身份编号 {{detail.person.verifiedIdentityRef}}</text><text class="s1-copy">负责人不可转交或撤销。工作人员仅属于当前店铺，按明确角色取得权限。</text><Stage1Field v-model="form.roleIds" label="角色" type="multi" :options="options" :disabled="busy||pending||detail?.person.owner||detail?.person.state==='REVOKED'" required @update:model-value="dirty=true"/><Stage1Field v-model="form.reason" label="授权原因" :maximum="500" :disabled="busy||pending" required @update:model-value="dirty=true"/><AppButton v-if="!detail?.person.owner&&detail?.person.state!=='REVOKED'" :disabled="pending" :loading="busy" @click="save">{{detail?'保存角色':'创建邀请'}}</AppButton></BaseCard><BaseCard v-if="issued" class="s1-form"><SectionHeader title="邀请已创建"/><text>接受截止 {{issued.expiresAt}}</text><text v-if="issued.invitationToken" class="s1-copy">口令仅在本页显示一次。受邀人正常登录后进入“接受邀请”，粘贴口令。请勿公开分享。</text><AppButton v-if="issued.invitationToken" @click="copy">复制邀请口令</AppButton><text v-else>未取得一次性口令，请到邀请列表撤销后重新创建。</text><AppButton variant="secondary" @click="back">返回人员列表</AppButton></BaseCard><BaseCard v-if="detail?.history.length" class="s1-form"><SectionHeader title="授权历史"/><view v-for="item in detail.history" :key="item.version"><text>第 {{item.version}} 版 · {{label(item.state)}}</text><text class="s1-copy">{{roleNames(item.roleIds)}} · {{item.at}}</text></view></BaseCard></template>
<template v-else><AppButton @click="edit()">邀请工作人员</AppButton><BaseCard v-for="person in people.records" :key="person.id" class="s1-form"><SectionHeader :title="person.displayName||'微信成员'"/><StatusTag>{{person.owner?'负责人':label(person.state)}}</StatusTag><text class="s1-copy">可信身份编号 {{person.verifiedIdentityRef}}</text><text>{{roleNames(person.roleIds)}}</text><AppButton variant="secondary" @click="edit(person.id)">查看授权与历史</AppButton><template v-if="!person.owner&&person.state!=='REVOKED'"><AppButton variant="quiet" @click="prepare(person,'staff',person.state==='ACTIVE'?'disable':'enable')">{{person.state==='ACTIVE'?'停用':'恢复'}}访问权限</AppButton><AppButton variant="quiet" @click="prepare(person,'staff','revoke')">撤销此人授权</AppButton></template></BaseCard><text v-if="!people.records.length">暂无人员记录。</text><view class="s1-row"><AppButton v-if="page>1" variant="quiet" @click="page--;load()">上一页人员</AppButton><AppButton v-if="page*20<people.total" variant="quiet" @click="page++;load()">下一页人员</AppButton></view><SectionHeader title="邀请与接受记录"/><BaseCard v-for="item in invitations.records" :key="item.id" class="s1-form"><StatusTag>{{label(item.status)}}</StatusTag><text>{{roleNames(item.roleIds)}}</text><text v-if="item.acceptedIdentity">{{item.acceptedIdentity.displayName}} · 可信身份编号 {{item.acceptedIdentity.verifiedIdentityRef}}</text><text class="s1-copy">{{item.status==='WAIT_OWNER_CONFIRM'?'确认截止 '+item.confirmDeadline:'接受截止 '+item.expiresAt}}</text><template v-if="item.status==='WAIT_OWNER_CONFIRM'"><AppButton @click="prepare(item,'staff-invitations','confirm')">核对身份并授权</AppButton><AppButton variant="quiet" @click="prepare(item,'staff-invitations','reject')">拒绝此人</AppButton></template><AppButton v-if="['INVITED','WAIT_OWNER_CONFIRM'].includes(item.status)" variant="quiet" @click="prepare(item,'staff-invitations','revoke')">撤销邀请</AppButton></BaseCard><text v-if="!invitations.records.length">暂无邀请。</text><view class="s1-row"><AppButton v-if="invitePage>1" variant="quiet" @click="invitePage--;load()">上一页邀请</AppButton><AppButton v-if="invitePage*20<invitations.total" variant="quiet" @click="invitePage++;load()">下一页邀请</AppButton></view></template>
<BaseCard v-if="action" class="s1-form"><SectionHeader title="核对并填写操作原因"/><Stage1Field v-model="action.reason" label="原因" required :disabled="busy||pending"/><AppButton :disabled="pending" :loading="busy" @click="execute">确认操作</AppButton><AppButton variant="quiet" :disabled="busy||pending" @click="action=null">取消</AppButton></BaseCard><AppButton variant="quiet" :loading="loading" @click="load">重新读取</AppButton></view></AppPage></template>
<style scoped lang="scss">.s1-staff{padding:$space-4 $page-gutter}.s1-form{display:flex;flex-direction:column;gap:$space-4;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-copy{display:block;color:$color-text-secondary;font-size:13px}.s1-row{display:flex;flex-wrap:wrap;gap:$space-2}</style>
